import numpy as np
def comps(block,color):
    b=np.array(block)==color
    seen=np.zeros_like(b); n=0; sizes=[]
    for i in range(b.shape[0]):
        for j in range(b.shape[1]):
            if b[i,j] and not seen[i,j]:
                n+=1; st=[(i,j)]; seen[i,j]=1; s=0
                while st:
                    y,x=st.pop(); s+=1
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            yy,xx=y+dy,x+dx
                            if 0<=yy<b.shape[0] and 0<=xx<b.shape[1] and b[yy,xx] and not seen[yy,xx]:
                                seen[yy,xx]=1; st.append((yy,xx))
                sizes.append(s)
    return n,sizes
print('9:',comps(nine,9))
